#!/usr/bin/env node
'use strict';
/*
 * Builds every generated file of the kit from its single source.
 *
 *   node tools/build.js          writes the generated files
 *   node tools/build.js --check  writes nothing; fails if any generated file is out of date
 *
 * Sources: participant/workbook/case-data.js (the case, the keys, the questions),
 * recorded/answers/ (the answers and their meta files), and the workbook's own
 * page files. Nothing here reads the network.
 */
const lib = require('./lib');

const GENERATED_NOTE = 'Generated by tools/build.js. Do not edit this file: change its source and run node tools/build.js.';

// -----------------------------------------------------------------------------
// recorded/answers -> participant/workbook/recorded-answers.js
// -----------------------------------------------------------------------------
function fillFacts(text, F, money, where) {
  return text.replace(/\{(money:)?([A-Za-z]+)\}/g, (all, isMoney, name) => {
    if (!(name in F)) { throw new Error(where + ': unknown fact {' + name + '}'); }
    return isMoney ? money(F[name]) : String(F[name]);
  });
}

function buildRecorded() {
  const CASE = lib.freshRequire('participant/workbook/case-data.js');
  const F = CASE.facts;
  const money = CASE.format.money;
  const metas = lib.listFiles('recorded/answers', (f) => f.endsWith('.meta.json'));
  const out = { ex1: null, ex2: null, ex3: [] };
  for (const rel of metas) {
    const meta = JSON.parse(lib.readText(rel));
    const answerRel = rel.replace(/\.meta\.json$/, '.txt');
    const entry = {
      file: answerRel,
      kind: meta.kind,
      note: meta.kind === 'constructed' ? meta.constructed_note : null,
      model: meta.model, date: meta.date, route: meta.route, edits: meta.edits,
      text: lib.readText(answerRel)
    };
    if (meta.issues) { entry.issues = meta.issues.map((t) => fillFacts(t, F, money, rel)); }
    if (meta.key) { entry.key = meta.key.map((k) => ({ accept: k.accept, reason: fillFacts(k.reason, F, money, rel) })); }
    if (meta.exercise === '1') { out.ex1 = entry; }
    else if (meta.exercise === '2') { out.ex2 = entry; }
    else if (meta.exercise === '3') { entry.id = meta.answer; out.ex3.push(entry); }
  }
  out.ex3.sort((a, b) => a.id.localeCompare(b.id));
  return [
    '/*',
    ' * The answers used in exercises 1, 2 and 3, with their keys.',
    ' * ' + GENERATED_NOTE,
    ' * Source: the files in recorded/answers.',
    ' */',
    '(function (root) {',
    '  \'use strict\';',
    '  var data = ' + JSON.stringify(out, null, 2).split('\n').join('\n  ') + ';',
    '  root.WorkshopRecorded = data;',
    '  if (typeof module === \'object\' && module.exports) { module.exports = data; }',
    '})(typeof globalThis !== \'undefined\' ? globalThis : this);',
    ''
  ].join('\n');
}

// -----------------------------------------------------------------------------
// Helpers for the generated documents
// -----------------------------------------------------------------------------
function cell(s) { return String(s).replace(/\|/g, '\\|').replace(/\n/g, ' '); }
function csvField(s) { const t = String(s); return /[",\n]/.test(t) ? '"' + t.replace(/"/g, '""') + '"' : t; }
function fence(text) { return '```text\n' + text.replace(/\n+$/, '') + '\n```'; }
function mdHeader(title) {
  return '# ' + title + '\n\n<!-- ' + GENERATED_NOTE + ' -->\n\n';
}
function standInNote(entry) {
  return entry.kind === 'constructed'
    ? '> **Not a recording.** ' + entry.note + '\n\n'
    : '> Recorded answer: model ' + entry.model + ', ' + entry.date + ', through ' + entry.route + '.' + (entry.edits ? ' Edits: ' + entry.edits : '') + '\n\n';
}

// -----------------------------------------------------------------------------
// Everything that is built from the case, the keys and the checker
// -----------------------------------------------------------------------------
function buildDocuments(recordedSource) {
  const files = {};
  files['participant/workbook/recorded-answers.js'] = recordedSource;
  // The checker reads recorded-answers.js from disk: main() writes it first when building.
  const { CASE, REC, checker } = lib.loadWorkbook();
  const F = CASE.facts;
  const C = checker;

  // --- request files, exactly as sent to an assistant -------------------------
  files['recorded/requests/ex1-request.txt'] = C.requestText('wish');
  files['recorded/requests/ex2-request.txt'] = C.requestText('summary');
  files['recorded/requests/ex3-request.txt'] = C.requestText('reply');

  // --- printable copies of the case -------------------------------------------
  files['participant/case/customer-thread.txt'] = CASE.threadText;
  files['participant/case/returns-policy.txt'] = CASE.policyText;
  files['participant/case/orders.csv'] =
    CASE.orders.columns.map((c) => csvField(c.label)).join(',') + '\n' +
    CASE.orders.rows.map((r) => CASE.orders.columns.map((c) => csvField(r[c.id])).join(',')).join('\n') + '\n';
  files['participant/case/snippets.txt'] =
    'Eight snippets someone might paste into an assistant (all invented)\n\n' +
    CASE.snippets.map((s) => 'Snippet ' + s.n + ': ' + s.title + '\nWhy someone might paste it: ' + s.purpose + '\n\n' + s.text + '\n').join('\n----------\n\n');

  // --- solutions that come straight from the keys -----------------------------
  files['solutions/ex1-strong-brief.txt'] = C.requestText('reply');
  files['solutions/ex3-marks.txt'] =
    '# Exercise 3: the key as a marks file. ' + GENERATED_NOTE + '\n' +
    REC.ex3.map((a) => a.key.map((k, i) => a.id + (i + 1) + ': ' + k.accept[0]).join('\n')).join('\n') + '\n';
  files['solutions/ex4-piles.txt'] =
    '# Exercise 4, part 1: the key as a piles file. ' + GENERATED_NOTE + '\n' +
    CASE.snippets.map((s) => s.n + ': ' + s.pile).join('\n') + '\n';
  files['solutions/ex4-extract.txt'] =
    C.makeExtract(CASE.orders.recommendedChoices).text + '\n' + CASE.orders.question + '\n';
  files['solutions/quiz-answers.txt'] =
    '# The ten-question check: the best answers. ' + GENERATED_NOTE + '\n' +
    CASE.quiz.map((q) => q.n + ': ' + q.options.find((o) => o.correct).key).join('\n') + '\n';

  files['solutions/ex3-annotated-answers.md'] = annotatedAnswers(CASE, REC, C);
  files['solutions/ex4-sorted-snippets.md'] = sortedSnippets(CASE);
  files['instructor/answer-key.md'] = answerKey(CASE, REC, C, F);

  // --- the single-file workbook ------------------------------------------------
  files['participant/workbook-single-file.html'] = singleFile(recordedSource);
  return files;
}

function labelName(C, id) { return C.LABELS.find((l) => l.id === id).label; }

function annotatedAnswers(CASE, REC, C) {
  let s = mdHeader('Exercise 3: the three answers, annotated');
  s += 'The request behind all three is `recorded/requests/ex3-request.txt` (the strong brief of exercise 1). ' +
    'Each sentence that ends with a full stop, a question mark or an exclamation mark is numbered; greetings and sign-offs are not.\n\n';
  for (const a of REC.ex3) {
    s += '## Answer ' + a.id + '\n\n' + standInNote(a);
    s += fence(a.text) + '\n\n';
    s += '| # | Sentence | Key | Why |\n|---|---|---|---|\n';
    C.numberedSentences(a.text).forEach((sent, i) => {
      const k = a.key[i];
      s += '| ' + a.id + (i + 1) + ' | ' + cell(sent) + ' | ' + k.accept.map((l) => labelName(C, l)).join(' or ') + ' | ' + cell(k.reason) + ' |\n';
    });
    s += '\n';
  }
  return s;
}

function sortedSnippets(CASE) {
  let s = mdHeader('Exercise 4, part 1: the eight snippets, sorted');
  s += 'This is a teaching key, not legal advice. An employer\'s own policy on AI tools comes first: where it is stricter, follow it.\n\n';
  for (const pile of CASE.piles) {
    s += '## ' + pile.label + '\n\n';
    for (const sn of CASE.snippets.filter((x) => x.pile === pile.id)) {
      s += '### Snippet ' + sn.n + ': ' + sn.title + '\n\n';
      s += '*Why someone might paste it:* ' + sn.purpose + '\n\n' + fence(sn.text) + '\n\n' + '**Why it goes here:** ' + sn.reason + '\n\n';
    }
  }
  return s;
}

function answerKey(CASE, REC, C, F) {
  const money = CASE.format.money;
  let s = mdHeader('Answer key');
  s += 'This page is generated from the workbook\'s own key, so it cannot drift from what the workbook marks. ' +
    'A test fails if it ever differs. Every business, person and figure in it is invented.\n\n' +
    'For each exercise: what a good answer holds, what the checker finds in the answer participants are given, and where the model answer is. ' +
    'How to use each part in the room is in `instructor/guide.md`.\n\n';

  // Exercise 1
  s += '## Exercise 1: From a wish to a brief\n\n';
  s += '### What is wrong with the answer to "' + CASE.briefs.wish.line + '"\n\n';
  s += 'The request is in `recorded/requests/ex1-request.txt`.\n\n' + standInNote(REC.ex1);
  s += REC.ex1.issues.map((t, i) => (i + 1) + '. ' + t).join('\n') + '\n\n';
  s += '### What the checker finds in that answer\n\n' + fence(C.formatResult(C.checkReply(REC.ex1.text))) + '\n\n';
  s += '### What the brief check looks for\n\n' +
    'It checks presence, not quality, and says so on the page.\n\n' +
    '| Part | The sign the checker looks for |\n|---|---|\n' +
    '| Situation | At least 12 words, and a word that says who is involved (I, we, the customer, the manager). |\n' +
    '| Material | The opening words of all ' + CASE.thread.length + ' messages of the thread. A note if the policy is missing. |\n' +
    '| Task | A word that says what to produce: write, draft, reply, summarise, and similar. |\n' +
    '| Form | A length (a number with words, sentences, paragraphs, lines or bullet points) or a structure (paragraphs, bullet points, a list, a table, headings). |\n' +
    '| Limits | At least one explicit prohibition: do not, don\'t, never, must not, avoid, or a sentence that starts with "No". |\n\n';
  s += '### Model answers\n\n' +
    '- A strong brief: `solutions/ex1-strong-brief.txt` (it is also the request behind exercise 3).\n' +
    '- A reply that follows it: `solutions/ex1-strong-reply.txt`.\n\n';

  // Exercise 2
  s += '## Exercise 2: Summarise, and prove it\n\n';
  s += '### What the summary must hold, and where each fact is\n\n| Fact | In the thread | Where |\n|---|---|---|\n';
  s += '| The order number | ' + F.orderNo + ' | Message 1, and every subject line |\n';
  s += '| The invoice number | ' + F.invoiceNo + ' | Message 3 |\n';
  s += '| What went wrong | Late: due ' + CASE.format.wdm(F.dates.due) + ', delivered ' + CASE.format.wdm(F.dates.promised) + '. Short: ' + F.cupsDelivered + ' of ' + F.cupsOrdered + ' cartons of cups. Damaged: ' + F.cupsCrushed + ' of the ' + F.cupsDelivered + ' crushed. | Messages 1 and 3 |\n';
  s += '| The amount in question | ' + money(F.creditAsked) + ': ' + money(F.creditDamaged) + ' for the damaged cartons (' + F.cupsCrushed + ' at ' + money(F.cupPrice) + ') and ' + money(F.localPurchase) + ' spent at a cash-and-carry | Message 5 |\n';
  s += '| What was promised | ' + F.staffFirst + ' promised delivery on ' + CASE.format.wdm(F.dates.promised) + ' (kept). He promised to confirm a day for the missing cartons by ' + CASE.format.wdm(F.dates.confirmBy) + ' (not kept). He did not promise a credit: he passed the request to ' + F.manager + '. | Messages 2, 4 and 5 |\n\n';
  s += '### The two traps\n\n' +
    '1. **The promise that was never given.** ' + F.contactFirst + ' asks for a credit (message 3) and later writes "the credit you promised" (message 5). ' +
    F.staffFirst + ' never promised one (message 4). A summary that reports her claim as a fact misleads the manager about what the company has already committed to.\n' +
    '2. **One figure, two meanings.** ' + F.cupsMissing + ' cartons never arrived, and ' + F.cupsCrushed + ' of those delivered arrived crushed. ' +
    'A summary that says "' + F.cupsCrushed + ' cartons were missing or damaged" halves the problem; one that says "' + (F.cupsMissing + F.cupsCrushed) + ' cartons were crushed" doubles the damage.\n\n';
  s += '### What the checker finds in the answer participants are given\n\n' + standInNote(REC.ex2) + fence(C.formatResult(C.checkSummary(REC.ex2.text))) + '\n\n';
  s += '### Model answer\n\nA strong summary: `solutions/ex2-strong-summary.txt`.\n\n';

  // Exercise 3
  s += '## Exercise 3: Find what is wrong\n\n';
  s += 'The request behind the three answers is `recorded/requests/ex3-request.txt`. The annotated answers, in full, are in `solutions/ex3-annotated-answers.md`.\n\n';
  s += '| # | Sentence | Key | Why |\n|---|---|---|---|\n';
  for (const a of REC.ex3) {
    const sentences = C.numberedSentences(a.text);
    a.key.forEach((k, i) => {
      s += '| ' + a.id + (i + 1) + ' | ' + cell(sentences[i]) + ' | ' + k.accept.map((l) => labelName(C, l)).join(' or ') + ' | ' + cell(k.reason) + ' |\n';
    });
  }
  s += '\n### What the automatic reply check finds in each answer\n\n' +
    'Use this in the debrief: the check catches some errors and misses others, which is the point of the exercise.\n\n' +
    '| Answer | ' + C.checkReply('').rules.map((r) => cell(r.name)).join(' | ') + ' |\n|---|' + C.checkReply('').rules.map(() => '---').join('|') + '|\n';
  for (const a of REC.ex3) {
    s += '| ' + a.id + ' | ' + C.checkReply(a.text).rules.map((r) => C.STATUS_WORDS[r.status]).join(' | ') + ' |\n';
  }
  s += '\n';

  // Exercise 4
  s += '## Exercise 4: What must not go in\n\n### Part 1: the eight snippets\n\n';
  s += '| # | Snippet | Pile | Why |\n|---|---|---|---|\n';
  for (const sn of CASE.snippets) {
    s += '| ' + sn.n + ' | ' + cell(sn.title) + ' | ' + CASE.piles.find((p) => p.id === sn.pile).label + ' | ' + cell(sn.reason) + ' |\n';
  }
  s += '\nThe piles, as a list, with each snippet\'s text: `solutions/ex4-sorted-snippets.md`.\n\n';
  s += '### Part 2: the extract\n\nThe choices that keep only what the question needs:\n\n| Column | Choice |\n|---|---|\n';
  const choiceName = { keep: 'Keep', standin: 'Replace with a stand-in', leave: 'Leave out' };
  for (const col of CASE.orders.columns) {
    s += '| ' + col.label + ' | ' + choiceName[CASE.orders.recommendedChoices[col.id]] + ' |\n';
  }
  s += '\nThe suggested question: "' + CASE.orders.question + '"\n\n';
  s += 'The extract these choices produce, with the question, is `solutions/ex4-extract.txt`. What the check says about it:\n\n' +
    fence(C.formatResult(C.checkExtract(C.makeExtract(CASE.orders.recommendedChoices).text))) + '\n\n';
  const totals = {};
  CASE.orders.rows.forEach((r) => { totals[r.business] = (totals[r.business] || 0) + Number(r.amount.replace(/[$,]/g, '')); });
  const repeat = Object.keys(totals).filter((b) => CASE.orders.rows.filter((r) => r.business === b).length > 1);
  s += 'What a correct answer says, once mapped back: ' + repeat.map((b) => b + ' has ' + CASE.orders.rows.filter((r) => r.business === b).length + ' orders, ' + money(totals[b]) + ' in total').join('; ') +
    '. ' + CASE.orders.rows.filter((r) => r.status !== 'Paid').length + ' of the ' + CASE.orders.rows.length + ' orders are not yet paid.\n\n';

  // Exercise 5
  s += '## Exercise 5: Make it reusable\n\n';
  s += 'Start from the summary request of exercise 2 (`recorded/requests/ex2-request.txt`). What must become a named placeholder:\n\n' +
    '- the material: the whole thread, as one placeholder such as [PASTE THE E-MAIL THREAD HERE];\n' +
    '- every person: ' + [F.manager, F.contact, F.staff].join(', ') + ';\n' +
    '- the customer: ' + F.customer + ';\n' +
    '- the order and invoice numbers, any amount, any date and any carton count, if they were copied in.\n\n' +
    'What may stay: the company\'s own name, the form (length, bullet points, message numbers) and the limits, which are true for every case.\n\n' +
    'The check needs at least 3 named placeholders, one of them for the material, no unnamed blank such as ___, and no value of this case. A strong template: `solutions/ex5-strong-template.txt`.\n\n';

  // Quiz
  s += '## The ten-question check\n\n| # | Objective | Best answer | Why |\n|---|---|---|---|\n';
  for (const q of CASE.quiz) {
    const best = q.options.find((o) => o.correct);
    s += '| ' + q.n + ' | ' + q.objective + ' | ' + best.key + ': ' + cell(best.text) + ' | ' + cell(best.why) + ' |\n';
  }
  s += '\n### Why each other option is wrong\n\n';
  for (const q of CASE.quiz) {
    s += '**Question ' + q.n + '.** ' + q.text + '\n\n';
    for (const o of q.options.filter((x) => !x.correct)) { s += '- **' + o.key + ': ' + o.text + '**  \n  Why not: ' + o.why + '\n'; }
    s += '\n';
  }
  return s;
}

// -----------------------------------------------------------------------------
// The single-file workbook: the page with its style and scripts inlined
// -----------------------------------------------------------------------------
function singleFile(recordedSource) {
  let html = lib.readText('participant/workbook/index.html');
  html = html.replace(/<link rel="stylesheet" href="([^"]+)">/g, (all, href) =>
    '<style>\n' + lib.readText('participant/workbook/' + href).replace(/<\/style/gi, '<\\/style') + '</style>');
  html = html.replace(/<script src="([^"]+)"><\/script>/g, (all, src) => {
    const code = src === 'recorded-answers.js' ? recordedSource : lib.readText('participant/workbook/' + src);
    return '<script>\n' + code.replace(/<\/script/gi, '<\\/script') + '</script>';
  });
  return html.replace('<!-- single-file-note -->', '<!-- ' + GENERATED_NOTE + ' Source: participant/workbook/. -->');
}

// -----------------------------------------------------------------------------
function main() {
  const check = process.argv.includes('--check');
  const recorded = buildRecorded();
  const recRel = 'participant/workbook/recorded-answers.js';
  if (!check && (!lib.exists(recRel) || lib.readText(recRel) !== recorded)) { lib.writeText(recRel, recorded); }
  const files = buildDocuments(recorded);
  const stale = [];
  for (const [rel, text] of Object.entries(files)) {
    const current = lib.exists(rel) ? lib.readText(rel) : null;
    if (current !== text) {
      stale.push(rel);
      if (!check) { lib.writeText(rel, text); }
    }
  }
  if (check) {
    if (stale.length) {
      console.log('These generated files are out of date. Run: node tools/build.js');
      stale.forEach((f) => console.log('  ' + f));
      process.exit(1);
    }
    console.log('All ' + Object.keys(files).length + ' generated files are current.');
  } else {
    console.log(stale.length ? 'Wrote ' + stale.length + ' file(s):\n  ' + stale.join('\n  ') : 'Nothing to write: all generated files are current.');
  }
}

module.exports = { buildRecorded, buildDocuments, GENERATED_NOTE };
if (require.main === module) { main(); }
